(332389, 24676, 3087, '<td valign="top">Very novel framing idea - a picture that draws one in and makes on look.</td>', 'Very novel framing idea - a picture that draws one in and makes on look.', '2003-06-20 06:46:01.000000', NULL, 1),
(332390, 25215, 3087, '<td valign="top">I''m not always a fan of high contrast or very dark images but I think this is an excellent example of both.</td>', 'I''m not always a fan of high contrast or very dark images but I think this is an excellent example of both.', '2003-06-20 06:46:41.000000', NULL, 1),
